var o=[{title:`Tipos habituales de paseo con carga`,text:`El paseo del granjero usa un peso en cada mano. El paseo de maleta usa un peso en un solo lado, así que el tronco tiene que resistir la inclinación lateral. El paseo frontal sostiene la carga cerca del pecho, y el paseo con carga por encima de la cabeza exige más estabilidad del hombro y más altura libre. Cada posición cambia los músculos y la habilidad que intervienen.`},{title:`Técnica básica`,text:`Elige una carga que puedas sostener con seguridad durante todo el recorrido, mantente erguido en una postura cómoda y camina con pasos deliberados. Mantén el peso sujeto con firmeza, no te inclines mucho hacia él ni en sentido contrario, y sigue respirando en un recorrido largo. Reduce la velocidad al girar y mantén tu camino despejado.`},{title:`Cómo dosificar los paseos con carga`,text:`Los paseos con carga se cuentan por distancia o por tiempo en lugar de por repeticiones. Por ejemplo, lleva dos mancuernas que puedas sostener con estabilidad durante 20–30 segundos, descansa y repite. Cuando tu agarre y tu postura se mantengan igual, añade un poco de distancia, tiempo o peso. Un peso mayor no ayuda si hace que tus pasos sean apresurados e irregulares.`},{title:`Espacio y seguridad`,text:`Comprueba que tu ruta tenga suficiente suelo libre, una superficie antideslizante y ninguna persona ni objeto en el camino. Deja los pesos en el suelo con control y no los dejes caer. Evita los paseos con carga por encima de la cabeza bajo un techo bajo o cuando no estés seguro del control de tu hombro. Entrena siempre los paseos de un solo lado en ambos lados.`},{title:`Cómo usar TrainUp`,text:`Los paseos con carga pueden ocupar un hueco de fuerza cuando tienes el equipamiento y espacio para caminar. Tu plan comprueba el tamaño de suelo que indicaste en Perfil. Si la espalda o las manos limitan cuánta carga sobre la columna o cuánto trabajo de agarre puedes asumir, añade esa zona del cuerpo como limitación en Perfil para que el plan pueda dejar fuera los ejercicios que no te convengan.`}];var s=[{label:`Biblioteca de ejercicios de ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: seguridad y fundamentos del entrenamiento de fuerza`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:o,sources:s};export{n as default,o as sections,s as sources};